    "UserProfileName": "宝玉",
    "UserProfilePic": "https://pbs.twimg.com/profile_images/561086911561736192/6_g58vEs_200x200.jpeg",
    "TweetText": "@jakevin7 没必要装全局 Skills\nhttps://x.com/dotey/status/2069632132431929651",
    "Tweet Url": "https://x.com/dotey/status/2079601179911172389",
    "TweetCreatedDate": "2026-07-21T16:15:33.000Z",
    "MediaType": "text",
    "MediaImageUrl": "",
